// Writes supabase/migrations/20261019230100_email_builder_seed.sql from kits.mjs and public/email-templates/.
//   node scripts/email-builder/build-seed.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { KITS } from "./kits.mjs";

const root = new URL("../../", import.meta.url).pathname;
const j = (o) => `$j$${JSON.stringify(o ?? {})}$j$::jsonb`;
const t = (s) => (s == null ? "null" : `$t$${s}$t$`);

let sql = `-- Email Builder seed (2026-10-19): brand kits + the four static templates as library rows.
-- Generated by scripts/email-builder/build-seed.mjs. Idempotent (on conflict do nothing).
-- ROLLBACK: delete from public.email_library where source = 'template';
--           delete from public.email_brand_kits;   -- (the schema migration's rollback drops the tables anyway)
-- The Elizabeth letter is NOT in this file: it carries her board link, so it is inserted as data by
-- scripts/email-builder/seed-elizabeth.mjs (reads the letter from a local path) and never committed.

`;

for (const k of KITS.filter((k) => k.slug !== "centering-you")) {
  sql += `insert into public.email_brand_kits (slug, name, kind, extends, source_client_slug, theme, header, signature, footer, product_ads, ad_policy, default_sender, assets, ai_images, voice, default_eyebrow, site_url, sort)
values (${t(k.slug)}, ${t(k.name)}, ${t(k.kind)}, ${t(k.extends ?? null)}, ${t(k.source_client_slug ?? null)}, ${j(k.theme)}, ${j(k.header)}, ${j(k.signature)}, ${j(k.footer)}, ${j(k.product_ads)}, ${j(k.ad_policy)}, ${j(k.default_sender)}, ${j(k.assets)}, ${t(k.ai_images ?? "allow")}, ${t(k.voice ?? null)}, ${t(k.default_eyebrow ?? null)}, ${t(k.site_url ?? null)}, ${k.sort ?? 100})
on conflict (slug) do nothing;\n\n`;
}

// Client kit: pulled from approval_clients / client_brand (palette, fonts, wordmark), then fine-tuned.
const cy = KITS.find((k) => k.slug === "centering-you");
sql += `-- Centering YOU: name, colors, fonts and wordmark come from approval_clients / client_brand.
do $$ begin
  if exists (select 1 from public.approval_clients where slug = 'centering-you') and not exists (select 1 from public.email_brand_kits where slug = 'centering-you') then
    perform public.email_kit_build('centering-you');
    update public.email_brand_kits set
      theme = theme || ${j({
        muted: "#52797a",
        font_heading: "Lora,Georgia,'Times New Roman',serif",
        font_css_url: "https://fonts.googleapis.com/css2?family=Lora:wght@400;500&display=swap",
        heading_weight: 500, heading_size: 30, heading_tracking: "-.01em",
        dark: { page_bg: "#1b2f30", card_bg: "#223c3d", card_border: "#2f4f50", text: "#EFE4D6", heading: "#EFE4D6", muted: "#b9cdc9", eyebrow: "#EF8F55", box_bg: "#2a4647", link: "#F4C459", rule: "#2f4f50" },
      })},
      voice = ${t(cy.voice)}, default_eyebrow = ${t(cy.default_eyebrow)}, site_url = ${t(cy.site_url)}
    where slug = 'centering-you';
  end if;
end $$;\n\n`;

// The four static templates, verbatim, as library rows (not editable as blocks; "Start from this" opens the builder with their kit).
const idx = JSON.parse(readFileSync(root + "public/email-templates/templates.json", "utf8"));
const kitFor = { Bestly: "bestly", InventoryProof: "inventoryproof" };
for (const e of idx) {
  const html = readFileSync(root + "public" + e.html, "utf8");
  if (html.includes("$h$")) throw new Error("html contains $h$");
  sql += `insert into public.email_library (brand_kit, title, subject, blocks, html, source, template_slug, status)
select ${t(kitFor[e.brand] ?? "bestly")}, ${t(e.name)}, ${t(e.subject)}, '[]'::jsonb, $h$${html}$h$, 'template', ${t(e.slug)}, 'draft'
where not exists (select 1 from public.email_library where template_slug = ${t(e.slug)});\n\n`;
}

writeFileSync(root + "supabase/migrations/20261019230100_email_builder_seed.sql", sql);
console.log("wrote seed,", sql.length, "bytes");
